krpano.action:
set(global.polyline_editor_active, false);
set(global.polyline_drawing, false);
set(global.polyline_counter, 1);
set(global.polyline_style, 'solid');
set(global.polyline_current_name, null);
set(global.polyline_point_count, 0);
call(init_polyline_counter_from_scene);

set(_maxpl, 0);
for(set(i, 0), i LT hotspot.count, inc(i),
	if(indexof(hotspot[get(i)].name, 'polyline_') == 0 AND indexof(hotspot[get(i)].name, '_layer') LT 0,
		calc(_idx, number(substring(hotspot[get(i)].name, 9)));
		if(_idx GT _maxpl, set(_maxpl, _idx));
	);
);
calc(global.polyline_counter, _maxpl + 1);

for(set(_try, 0), _try LT 500, inc(_try),
	if(hotspot[get(global.polyline_current_name)] !== null,
		inc(global.polyline_counter);
		txtadd(global.polyline_current_name, 'polyline_', get(global.polyline_counter));
	,
		break();
	);
);

if(global.polyline_editor_active == true,
	set(global.polyline_editor_active, false);
	set(layer[polyline_editor_panel].visible, false);
,
	set(global.polyline_editor_active, true);
	set(layer[polyline_editor_panel].visible, true);
);

set(global.polyline_drawing, true);
set(global.polyline_point_count, 0);
txtadd(global.polyline_current_name, 'polyline_', get(global.polyline_counter));
call(find_free_polyline_name);
set(global.phedrawing, false);

addhotspot(get(global.polyline_current_name));
set(hotspot[get(global.polyline_current_name)].polyline, true);
set(hotspot[get(global.polyline_current_name)].distorted, true);
set(hotspot[get(global.polyline_current_name)].visible, true);
set(hotspot[get(global.polyline_current_name)].alpha, 1.0);
set(hotspot[get(global.polyline_current_name)].zorder, 9999);
set(hotspot[get(global.polyline_current_name)].capture, false);
set(hotspot[get(global.polyline_current_name)].fillalpha, 0.0);
set(hotspot[get(global.polyline_current_name)].bordercolor, 0xFF6B00);
set(hotspot[get(global.polyline_current_name)].borderwidth, 8.0);
set(hotspot[get(global.polyline_current_name)].borderalpha, 0.9);

set(global.polyline_drawing, true);
set(global.polyline_point_count, 0);
trace('Iniziato disegno di nuova linea - clicca sulla panorama per aggiungere punti, SPACE per finire');

if(global.polyline_drawing == true,
	screentosphere(global.mouse.x, global.mouse.y, point_ath, point_atv);
	set(hotspot[get(global.polyline_current_name)].point[get(global.polyline_point_count)].ath, get(point_ath));
	set(hotspot[get(global.polyline_current_name)].point[get(global.polyline_point_count)].atv, get(point_atv));

	// Marker visibile per debug
	calc(_ptname, 'polyline_pt_' + global.polyline_counter + '_' + global.polyline_point_count);
	addhotspot(get(_ptname));
	set(hotspot[get(_ptname)].type, text);
	set(hotspot[get(_ptname)].distorted, true);
	set(hotspot[get(_ptname)].width, 8);
	set(hotspot[get(_ptname)].height, 8);
	set(hotspot[get(_ptname)].bgcolor, 0xFFFF00);
	set(hotspot[get(_ptname)].bgalpha, 1.0);
	set(hotspot[get(_ptname)].bgroundedge, 4);
	set(hotspot[get(_ptname)].zorder, 10000);
	set(hotspot[get(_ptname)].capture, false);
	set(hotspot[get(_ptname)].ath, get(point_ath));
	set(hotspot[get(_ptname)].atv, get(point_atv));

	inc(global.polyline_point_count);
	updatescreen();
	calc(_plptmsg, 'Punto aggiunto: ath=' + get(point_ath) + ' atv=' + get(point_atv) + ' (totale: ' + global.polyline_point_count + ')');
	trace(get(_plptmsg));
);

if(global.polyline_drawing == true,
	set(global.polyline_drawing, false);
	set(hotspot[get(global.polyline_current_name)].enabled, true);

	generate_polyline_code();
	// Rimuovi marker gialli di debug
	for(set(i, hotspot.count-1), i GE 0, dec(i),
		if(indexof(hotspot[get(i)].name, 'polyline_pt_') == 0,
			removehotspot(get(i));
		);
	);
	inc(global.polyline_counter);
	calc(_pldone, 'Linea completata con ' + global.polyline_point_count + ' punti');
	trace(get(_pldone));
);

		calc(polyline_code, '<hotspot name="' + get(global.polyline_current_name) + '" polyline="true" borderwidth="8.0" bordercolor="0xFF6B00" borderalpha="0.9" distorted="true">');

		for(set(i, 0), i LT global.polyline_point_count, inc(i),
			if(hotspot[get(global.polyline_current_name)].point[get(i)].ath != null AND hotspot[get(global.polyline_current_name)].point[get(i)].atv != null,
				calc(polyline_code, get(polyline_code) + '
	<point ath="' + hotspot[get(global.polyline_current_name)].point[get(i)].ath + '" atv="' + hotspot[get(global.polyline_current_name)].point[get(i)].atv + '" />');
			);
		);

		calc(polyline_code, get(polyline_code) + '
</hotspot>');

		set(layer[polyline_code_panel].html, get(polyline_code));
		trace('Codice generato - clicca SHOW CODE per visualizzarlo');
